parameters.content:
// Query to find all shortest paths from Arsenal station using Dijkstra's algorithm
// This query finds shortest paths from Arsenal to all other Underground stations

// Method 1: Using Neo4j's built-in shortestPath function
// This finds the shortest path between Arsenal and each other station
MATCH (start:UndergroundStation {name: 'Arsenal'})
MATCH (end:UndergroundStation)
WHERE start <> end

CALL {
    WITH start, end
    MATCH path = shortestPath((start)-[:LINK*]-(end))
    WITH path, 
         reduce(totalDist = 0, rel IN relationships(path) | totalDist + rel.distance) as totalDistance,
         [n IN nodes(path) | n.name] AS pathNames

    // Calculate cumulative distances along the path
    WITH pathNames, totalDistance, path,
         reduce(cumDistances = [0.0], i IN range(0, size(relationships(path))-1) |
             cumDistances + [cumDistances[-1] + relationships(path)[i].distance]
         ) AS cumulativeDistances

    RETURN pathNames, cumulativeDistances, totalDistance
    ORDER BY totalDistance
    LIMIT 1
}

RETURN pathNames as path, cumulativeDistances, totalDistance
ORDER BY totalDistance
LIMIT 50;  // Limit to first 50 results for readability

// Alternative Method 2: Using APOC procedures (if APOC is installed)
/*
MATCH (start:UndergroundStation {name: 'Arsenal'})
CALL apoc.path.expandConfig(start, {
    relationshipFilter: "LINK",
    labelFilter: "UndergroundStation",
    minLevel: 1,
    uniqueness: "NODE_GLOBAL"
}) YIELD path, weight
WITH path, 
     [n IN nodes(path) | n.name] AS pathNames,
     reduce(totalDist = 0, rel IN relationships(path) | totalDist + rel.distance) as totalDistance,
     reduce(cumDistances = [0.0], i IN range(0, size(relationships(path))-1) |
         cumDistances + [cumDistances[-1] + relationships(path)[i].distance]
     ) AS cumulativeDistances
WHERE totalDistance > 0
RETURN pathNames, cumulativeDistances, totalDistance
ORDER BY totalDistance;
*/

// Method 3: Simple direct neighbors first (for testing)
/*
MATCH (start:UndergroundStation {name: 'Arsenal'})-[r:LINK]-(neighbor:UndergroundStation)
RETURN ['Arsenal', neighbor.name] as path, [0.0, r.distance] as cumulativeDistances, r.distance as totalDistance
ORDER BY r.distance;
*/

// Method 4: Two-hop paths (for validation)
/*
MATCH path = (start:UndergroundStation {name: 'Arsenal'})-[:LINK]-()-[:LINK]-(end:UndergroundStation)
WHERE start <> end
WITH path, 
     [n IN nodes(path) | n.name] AS pathNames,
     reduce(totalDist = 0, rel IN relationships(path) | totalDist + rel.distance) as totalDistance
WITH pathNames, totalDistance,
     reduce(cumDistances = [0.0], i IN range(0, size(relationships(path))-1) |
         cumDistances + [cumDistances[-1] + relationships(path)[i].distance]
     ) AS cumulativeDistances
RETURN pathNames, cumulativeDistances, totalDistance
ORDER BY totalDistance
LIMIT 20;
*/

