import json
from neo4j import GraphDatabase

uri = "bolt://localhost:7687"
user = "neo4j"
password = "12345678"

driver = GraphDatabase.driver(uri, auth=(user, password))

with driver.session() as session:
    query = """
    MATCH (source:UndergroundStation {name: 'Arsenal'})
    MATCH (target:UndergroundStation)
    WHERE source <> target
    WITH source, target
    MATCH p = shortestPath((source)-[rel:LINK*]-(target))
    WHERE p IS NOT NULL
    WITH [node in nodes(p) | node.name] as nodePath, relationships(p) as rels,
         reduce(sum = 0, r in relationships(p) | sum + r.distance) as totalDist
    RETURN nodePath, rels, totalDist
    ORDER BY totalDist, nodePath
    """

    results = session.run(query)

    for record in results:
        node_path = record["nodePath"]
        rels = record["rels"]

        # Compute cumulative distances in Python
        cumulative = [0.0]
        for rel in rels:
            cumulative.append(cumulative[-1] + rel['distance'])

        print(f'{json.dumps(node_path)}: {cumulative}')

driver.close()
EOF
