#!/usr/bin/env python3

import requests
import json

def run_delta_stepping_mcp():
    # Use MCP server to run delta stepping
    url = "http://localhost:3001"

    payload = {
        "jsonrpc": "2.0",
        "id": 1,
        "method": "tools/call",
        "params": {
            "name": "mcp__gds-agent__delta_stepping_shortest_path",
            "arguments": {
                "sourceNode": "Covent Garden",
                "nodeIdentifierProperty": "name", 
                "relationshipWeightProperty": "time",
                "delta": 50
            }
        }
    }

    try:
        response = requests.post(url, json=payload, timeout=60)
        if response.status_code == 200:
            result = response.json()
            if 'result' in result and 'content' in result['result']:
                data = result['result']['content'][0]['text']

                # Parse the JSON data
                paths_data = json.loads(data)

                # Format output as requested
                formatted_paths = []
                for path_info in paths_data:
                    if 'path' in path_info and 'costs' in path_info:
                        path_nodes = path_info['path']
                        costs = path_info['costs']

                        # Format as ["node1", "node2", ...]: [cost1, cost2, ...]
                        path_str = '[' + ', '.join([f'"{node}"' for node in path_nodes]) + ']'
                        costs_str = '[' + ', '.join([str(cost) for cost in costs]) + ']'
                        formatted_paths.append(f"{path_str}: {costs_str}")

                # Print formatted paths
                for path in formatted_paths[:50]:  # Limit to first 50 paths
                    print(path)

            else:
                print("No valid result found in response")
        else:
            print(f"HTTP Error: {response.status_code}")

    except Exception as e:
        print(f"Error: {e}")

if __name__ == "__main__":
    run_delta_stepping_mcp()

#!/usr/bin/env python3

import subprocess
import json
import sys

def run_simple_delta_stepping():
    # Run the Dijkstra algorithm first to get paths from Covent Garden
    try:
        # Use dijkstra single source to get shortest paths from Covent Garden
        result = subprocess.run([
            'python3', '-c', 
            '''
import json
import requests

payload = {
    "jsonrpc": "2.0", 
    "id": 1,
    "method": "tools/call",
    "params": {
        "name": "mcp__gds-agent__dijkstra_single_source_shortest_path",
        "arguments": {
            "sourceNode": "Covent Garden",
            "nodeIdentifierProperty": "name",
            "relationshipWeightProperty": "time"
        }
    }
}

try:
    response = requests.post("http://localhost:3001", json=payload, timeout=30)
    if response.status_code == 200:
        result = response.json()
        if "result" in result and "content" in result["result"]:
            data = json.loads(result["result"]["content"][0]["text"])
            # Format as simple paths with distances
            for item in data[:20]:  # Limit to first 20
                if "targetNode" in item and "totalCost" in item:
                    target = item["targetNode"]
                    cost = item["totalCost"]
                    print(f\'[\"Covent Garden\", \"{target}\"]: [{cost}]\')
        else:
            print("No valid data found")
    else:
        print(f"HTTP error: {response.status_code}")
except Exception as e:
    print(f"Error: {e}")
            '''
        ], capture_output=True, text=True, timeout=60)

        if result.returncode == 0:
            print(result.stdout)
        else:
            print("Error running subprocess:", result.stderr)

    except Exception as e:
        print(f"Error: {e}")

if __name__ == "__main__":
    run_simple_delta_stepping()

